fn BEg_source_leaf_grammar() {
    let q=[0u8;832];
    let l=core::cell::Cell::new(0);let r=core::cell::Cell::new(0);
    let actual=batch_leaf(BEg_Hash(&l),0,&q);
    let expected=private_leaf_hash_with_digest(BEg_Hash(&r),merkle::C1_TAG,&q[..480],&[0;32]);
    assert_eq!(actual,expected);assert_eq!(l.get(),1);assert_eq!(r.get(),1);
    kani::cover!(l.get()==1);
}

fn BEg_accepted_single_tail() {
    let proof=vec![0;compact::PROOF_BYTES];
    let root=[205,128,89,8,101,71,218,225,175,221,221,113,182,122,230,152,94,194,169,107,137,237,162,203,160,65,146,202,114,58,100,131];
    let hash=aspis_core::digest::LegacyHashFn(BEg_sha);
    let mut idx:[u32;16]=kani::any();let mut val:[[u8;32];16]=kani::any();
    idx[0]=0;val[0]=batch_leaf(hash,0,&[0;832]);
    let before_idx=idx;let before_val=val;
    let calls=core::cell::Cell::new(0);
    let out=BEg_source_tail(&proof,root,0,&mut idx,&mut val,1,BEg_Hash(&calls));
    assert_eq!(out,Ok(()));assert_eq!(calls.get(),18);
    let j:usize=kani::any();kani::assume(j>0&&j<16);
    assert_eq!(idx[j],before_idx[j]);
    for b in 0..32 {assert_eq!(val[j][b],before_val[j][b]);}
    kani::cover!(out==Ok(()));
}

fn BEg_same_index() {
    let x:[u32;16]=kani::any();let j:usize=kani::any();kani::assume(j<16);
    let y:u32=kani::any();assert_eq!(same_batch_index(&x,j,y),x[j]==y);
    kani::cover!(same_batch_index(&x,j,y));kani::cover!(!same_batch_index(&x,j,y));
}

fn BEg_same_leaf() {
    let x:[[u8;32];16]=kani::any();let j:usize=kani::any();kani::assume(j<16);
    let y:[u8;32]=kani::any();let mut equal=true;
    for k in 0..32 {if x[j][k]!=y[k] {equal=false;}}
    assert_eq!(same_batch_leaf(&x,j,y),equal);
    kani::cover!(equal);kani::cover!(!equal);
}

fn BEg_accepted_tx1() {
    let proof=vec![0;compact::PROOF_BYTES];let roots=BEg_zero_roots();
    let actual=core::cell::Cell::new(0);let reference=core::cell::Cell::new(0);
    let out=batch_merkle_values(&proof,[0;22],roots,0,BEg_Hash(&actual));
    let expected=BEg_reference(&proof,[0;22],roots,0,BEg_Hash(&reference));
    assert_eq!(out,expected);assert_eq!(out,Ok(()));
    assert_eq!(actual.get(),reference.get());
    kani::cover!(out==Ok(()));
}
